@SpringBootTest(properties={"testhub.registration.enabled=true","testhub.bootstrap.demo-enabled=false"})
@AutoConfigureMockMvc @ActiveProfiles(resolver=FunctionalDatabaseProfile.class) @DirtiesContext
class GrpcDescriptorSyncFlowTests {
 @TempDir static Path directory;
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){if(FunctionalDatabaseProfile.mysql())FunctionalDatabaseProfile.configure(r,directory,"grpc-sync-fixture");else{r.add("testhub.desktop.data-directory",directory::toString);r.add("spring.datasource.url",()->"jdbc:h2:file:"+directory.resolve("workspace")+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_ON_EXIT=FALSE");r.add("spring.datasource.username",()->"sa");r.add("spring.datasource.password",()->"grpc-sync-fixture");}}
 @Autowired RegistrationService registration; @Autowired AccessService access; @Autowired GrpcDescriptorService descriptors; @Autowired GrpcDescriptorTransferService transfer; @Autowired GrpcDescriptorSyncService sync; @Autowired ApiDesignService design; @Autowired ApiDesignSyncService apiSync; @Autowired ObjectMapper json; @Autowired JdbcClient jdbc; @Autowired MockMvc mvc; @Autowired PlatformTransactionManager manager;
 record Fixture(PlatformUserPrincipal actor,String project){}
 Fixture fixture(){String account="grpc-sync-"+UUID.randomUUID();var actor=new PlatformUserPrincipal(registration.register(account,account+"@example.test","描述符验收","Grpc-fixture-2026!"));var c=access.context(actor);return new Fixture(actor,c.projects().get(c.organizations().getFirst().id()).getFirst().id());}
 byte[] bytes(String service){return FileDescriptorSet.newBuilder().addFile(FileDescriptorProto.newBuilder().setName("owned.proto").setPackage("owned").setSyntax("proto3").addMessageType(DescriptorProto.newBuilder().setName("Message").addField(FieldDescriptorProto.newBuilder().setName("text").setNumber(1).setType(FieldDescriptorProto.Type.TYPE_STRING))).addService(ServiceDescriptorProto.newBuilder().setName(service).addMethod(MethodDescriptorProto.newBuilder().setName("Unary").setInputType(".owned.Message").setOutputType(".owned.Message")))).build().toByteArray();}
 GrpcDescriptorService.Summary upload(Fixture f,String name,byte[] bytes){return descriptors.importFiles(f.actor(),f.project(),name,List.of(new MockMultipartFile("files","owned.pb","application/octet-stream",bytes)));}
 GrpcDescriptorSyncService.Snapshot snapshot(Fixture f){return sync.snapshot(f.actor(),f.project(),f.actor().userId());}
 GrpcDescriptorSyncService.Request request(Fixture s,Fixture t,GrpcDescriptorService.Summary source,byte[] bytes){return new GrpcDescriptorSyncService.Request(UUID.randomUUID().toString(),t.actor().userId(),snapshot(t).revision(),s.project(),source.id(),source.name(),FunctionalTransferFiles.sha256(bytes),bytes);}
 String route(Fixture f){return "/api/v1/projects/"+f.project()+"/api-debug/grpc/descriptors/sync";}
 @Test void copyPreservesBytesAndDiscoveryWithNewIdentityAndDurableExactReplay(){var s=fixture();var t=fixture();var bytes=bytes("Echo");var original=upload(s,"离线接口",bytes);var r=request(s,t,original,bytes);var receipt=sync.apply(t.actor(),t.project(),r);assertNotEquals(original.id(),receipt.item().id());assertArrayEquals(bytes,sync.content(t.actor(),t.project(),t.actor().userId(),receipt.item().id()));assertEquals(receipt,sync.apply(t.actor(),t.project(),r));assertEquals(1,descriptors.list(t.actor(),t.project()).size());assertEquals(List.of("owned.Echo"),descriptors.discover(t.actor(),t.project(),receipt.item().id(),null).services());assertEquals("UNARY",descriptors.discover(t.actor(),t.project(),receipt.item().id(),"owned.Echo").methods().getFirst().callType());}
 @Test void existingIdenticalDescriptorIsKeptAndDifferentContentCannotOverwrite(){var s=fixture();var t=fixture();var bytes=bytes("Echo");var source=upload(s,"接口",bytes);upload(t,"接口",bytes);var old=descriptors.list(t.actor(),t.project()).getFirst();var receipt=sync.apply(t.actor(),t.project(),request(s,t,source,bytes));assertEquals(old.id(),receipt.item().id());assertEquals(old,descriptors.list(t.actor(),t.project()).getFirst());var other=bytes("Other");var fake=new GrpcDescriptorService.Summary(source.id(),source.name(),"DESCRIPTOR_SET",other.length,1,1,null);assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),request(s,t,fake,other)));assertArrayEquals(bytes,sync.content(t.actor(),t.project(),t.actor().userId(),old.id()));}
 @Test void receiptCannotRecreateDeletedTargetOrReuseUuidForOtherContents(){var s=fixture();var t=fixture();var bytes=bytes("Echo");var source=upload(s,"接口",bytes);var r=request(s,t,source,bytes);var receipt=sync.apply(t.actor(),t.project(),r);var changed=new GrpcDescriptorSyncService.Request(r.requestKey(),r.expectedUserId(),r.expectedRevision(),r.sourceProject(),r.sourceId(),"其他",r.sha256(),r.content());assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),changed));descriptors.delete(t.actor(),t.project(),receipt.item().id());assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),r));assertTrue(descriptors.list(t.actor(),t.project()).isEmpty());}
 @Test void actorScopeWriterAndCsrfAreEnforced()throws Exception{var s=fixture();var t=fixture();var source=upload(s,"接口",bytes("Echo"));var r=request(s,t,source,bytes("Echo"));mvc.perform(post(route(t)).with(user(t.actor())).contentType("application/json").content(json.writeValueAsBytes(r))).andExpect(status().isForbidden());mvc.perform(get(route(t)).with(user(s.actor())).param("expectedUserId",s.actor().userId())).andExpect(status().isForbidden());assertThrows(ResponseStatusException.class,()->sync.snapshot(t.actor(),t.project(),s.actor().userId()));jdbc.sql("UPDATE membership SET role_code='VIEWER' WHERE user_id=:u").param("u",t.actor().userId()).update();mvc.perform(get(route(t)).with(user(t.actor())).param("expectedUserId",t.actor().userId())).andExpect(status().isForbidden());mvc.perform(post(route(t)).with(user(t.actor())).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(r))).andExpect(status().isForbidden());}
 @Test void staleInventoryRejectsCopyAndTransactionRollbackLeavesNoRowsOrReceipts(){var s=fixture();var t=fixture();var source=upload(s,"接口",bytes("Echo"));var r=request(s,t,source,bytes("Echo"));upload(t,"已有",bytes("Old"));assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),r));var fresh=request(s,t,source,bytes("Echo"));new TransactionTemplate(manager).executeWithoutResult(tx->{sync.apply(t.actor(),t.project(),fresh);tx.setRollbackOnly();});assertEquals(1,descriptors.list(t.actor(),t.project()).size());assertEquals(0,jdbc.sql("SELECT COUNT(*) FROM grpc_descriptor_sync_receipt WHERE project_id=:p").param("p",t.project()).query(Integer.class).single());}
 @Test void invalidDigestDependenciesEmptyContentAndUnknownJsonAreRejected()throws Exception{var s=fixture();var t=fixture();var source=upload(s,"接口",bytes("Echo"));var good=request(s,t,source,bytes("Echo"));var tree=(com.fasterxml.jackson.databind.node.ObjectNode)json.valueToTree(good);tree.put("unsupported",true);assertThrows(ResponseStatusException.class,()->sync.decode(json.writeValueAsBytes(tree)));assertThrows(ResponseStatusException.class,()->sync.decode("null".getBytes()));assertEquals(413,assertThrows(ResponseStatusException.class,()->sync.decode(new byte[GrpcDescriptorSyncService.MAX_BODY+1])).getStatusCode().value());for(var raw:List.of(new byte[0],new byte[]{1},FileDescriptorSet.newBuilder().addFile(FileDescriptorProto.newBuilder().setName("bad.proto").addDependency("missing.proto")).build().toByteArray())){var r=new GrpcDescriptorSyncService.Request(good.requestKey(),good.expectedUserId(),good.expectedRevision(),s.project(),source.id(),source.name(),FunctionalTransferFiles.sha256(raw),raw);assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),r));}var bad=new GrpcDescriptorSyncService.Request(good.requestKey(),good.expectedUserId(),good.expectedRevision(),s.project(),source.id(),source.name(),"0".repeat(64),good.content());assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),bad));assertTrue(descriptors.list(t.actor(),t.project()).isEmpty());}
 @Test void corruptStoredBytesAndCountsCannotPassIndexContentOrCaseReference(){var f=fixture();var row=upload(f,"损坏",bytes("Echo"));jdbc.sql("UPDATE grpc_descriptor SET descriptor_bytes=:b WHERE project_id=:p AND id=:id").param("b",bytes("Other")).param("p",f.project()).param("id",row.id()).update();assertThrows(ResponseStatusException.class,()->snapshot(f));assertThrows(ResponseStatusException.class,()->sync.content(f.actor(),f.project(),f.actor().userId(),row.id()));assertThrows(ResponseStatusException.class,()->sync.validateReference(f.project(),row.id()));}
 @Test void exactOneMiBCompiledBytesAndFourMiBTotalArePreservedWhileOverflowIsRejected()throws Exception{var s=fixture();var t=fixture();var base=FileDescriptorSet.parseFrom(bytes("Echo"));byte[] raw=null;for(int pad=1024*1024-base.getSerializedSize()-16;pad<1024*1024-base.getSerializedSize();pad++){var candidate=base.toBuilder().setUnknownFields(com.google.protobuf.UnknownFieldSet.newBuilder().addField(100,com.google.protobuf.UnknownFieldSet.Field.newBuilder().addLengthDelimited(com.google.protobuf.ByteString.copyFrom(new byte[pad])).build()).build()).build().toByteArray();if(candidate.length==1024*1024){raw=candidate;break;}}assertNotNull(raw);var immutable=raw;
  for(int n=0;n<4;n++){String sourceId=Ulid();String name="边界"+n;var r=new GrpcDescriptorSyncService.Request(UUID.randomUUID().toString(),t.actor().userId(),snapshot(t).revision(),s.project(),sourceId,name,FunctionalTransferFiles.sha256(raw),raw);var receipt=sync.apply(t.actor(),t.project(),r);assertArrayEquals(raw,sync.content(t.actor(),t.project(),t.actor().userId(),receipt.item().id()));}
  assertEquals(4,snapshot(t).items().size());var overflow=new GrpcDescriptorSyncService.Request(UUID.randomUUID().toString(),t.actor().userId(),snapshot(t).revision(),s.project(),Ulid(),"额外",FunctionalTransferFiles.sha256(bytes("Small")),bytes("Small"));assertThrows(ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),overflow));var oversized=Arrays.copyOf(immutable,immutable.length+1);var bad=new GrpcDescriptorSyncService.Request(UUID.randomUUID().toString(),s.actor().userId(),snapshot(s).revision(),t.project(),Ulid(),"超限",FunctionalTransferFiles.sha256(oversized),oversized);assertThrows(ResponseStatusException.class,()->sync.apply(s.actor(),s.project(),bad));assertEquals(4,descriptors.list(t.actor(),t.project()).size());}
 String Ulid(){return com.github.f4b6a3.ulid.UlidCreator.getUlid().toString();}
 @Test void twentyDescriptorLimitDoesNotTruncateInventory(){var f=fixture();for(int n=0;n<21;n++)upload(f,"接口"+n,bytes("Echo"));assertThrows(ResponseStatusException.class,()->snapshot(f));assertEquals(21,descriptors.list(f.actor(),f.project()).size());}
 @Test void contentDownloadHasDigestAndAttachmentHeaders()throws Exception{var f=fixture();var raw=bytes("Echo");var row=upload(f,"接口",raw);mvc.perform(get(route(f)+"/"+row.id()+"/content").with(user(f.actor())).param("expectedUserId",f.actor().userId())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("X-Content-SHA256",FunctionalTransferFiles.sha256(raw))).andExpect(content().bytes(raw));}
 @Test void caseSyncAcceptsOnlyValidTargetProjectDescriptorIdsAndPreservesOtherFields(){var s=fixture();var t=fixture();var raw=bytes("Echo");var source=upload(s,"接口",raw);var copied=sync.apply(t.actor(),t.project(),request(s,t,source,raw));var catalog=design.createCatalog(t.actor(),t.project(),new ApiDesignService.CatalogInput("目录",null,0));var api=design.createDefinition(t.actor(),t.project(),new ApiDesignService.DefinitionInput(catalog.id(),"POST","/grpc","接口","1.0.0","","",List.of(),List.of(),List.of(),"","",Map.of()));
  var snapshot=json.createObjectNode().put("protocol","GRPC").put("descriptorId",copied.item().id()).put("service","owned.Echo").put("requestJson","{\"text\":\"kept\"}");var item=new ApiDesignSyncProjection.Item("CASE","POST /grpc\n离线用例",Map.of("environmentCode","dev","requestSnapshot",snapshot,"expectedStatus",200,"responseValidation","keep","savedResponseBody","original"));
  // Null environment avoids depending on a configured network environment.
  var data=new LinkedHashMap<>(item.definition());data.put("environmentCode",null);item=new ApiDesignSyncProjection.Item(item.kind(),item.name(),data);var valid=item;
  java.util.function.Function<ApiDesignSyncProjection.Item,ApiDesignSyncService.Request> req=i->new ApiDesignSyncService.Request(UUID.randomUUID().toString(),t.actor().userId(),apiSync.snapshot(t.actor(),t.project(),t.actor().userId()).revision(),List.of(new ApiDesignSyncService.Operation(UUID.randomUUID().toString(),i)));
  apiSync.apply(t.actor(),t.project(),req.apply(valid));var actual=design.cases(t.actor(),t.project(),api.id()).getFirst();assertEquals(copied.item().id(),actual.requestSnapshot().path("descriptorId").asText());assertEquals("original",actual.savedResponseBody());assertEquals("keep",actual.responseValidation());snapshot.put("descriptorId",source.id());assertThrows(ResponseStatusException.class,()->apiSync.apply(t.actor(),t.project(),req.apply(valid)));assertEquals(copied.item().id(),design.cases(t.actor(),t.project(),api.id()).getFirst().requestSnapshot().path("descriptorId").asText());}
}
